/** Normalizes a tech name so "next.js" / "NextJs" match "Next.js". */
function normalize(name: string): string {
  return name.toLowerCase().replace(/[.\s\-]/g, '')
}

const byKey = new Map<string, string>()
for (const name of Object.keys(techIcons)) {
  byKey.set(normalize(name), name)
}

export type ResolvedTech = { name: string; path: string; hex: string }

/** Resolves a tech name to its canonical brand entry, or null. */
export function resolveTech(name: string): ResolvedTech | null {
  const canonical = byKey.get(normalize(name))
  if (canonical) {
    const entry = techIcons[canonical]
    return { name: canonical, path: entry.path, hex: entry.hex }
  }
  return null
}

export function TechMark({ name, className }: { name: string; className?: string }) {
  const tech = resolveTech(name)
  if (!tech) return null
  return (
    <svg viewBox="0 0 24 24" fill={tech.hex} aria-hidden="true" className={className}>
      <path d={tech.path} />
    </svg>
  )
}
